
import { validationResult } from "express-validator"; // Imports the function that collects validation errors from the request.
import { ApiError } from "../utils/api-error.js"; // Imports the custom API error class.

// Defines middleware to check whether the incoming request data is valid.
export const validateRequest = (req, res, next) => {

    // Retrieves validation errors generated by previous express-validator rules.
    const errors = validationResult(req);

    // Checks whether the request has passed all validation rules.
    if (errors.isEmpty()) {

        // If there are no errors, passes control to the next middleware or controller.
        return next();
    }

    // Creates an empty array to store validation errors in a structured format.
    const extractedErrors = [];

    // Loops through every validation error found in the request.
    errors.array().forEach((err) => {

        // Stores each error as an object containing the field name and error message.
        // Example: { email: "Please enter a valid email address" }
        extractedErrors.push({ [err.path]: err.msg });
    });

    // Passes a custom API error to Express error middleware.
    // HTTP 422 = Unprocessable Entity; extractedErrors holds each field message.
    return next(
        new ApiError(
            422,
            "Received data is not valid",
            extractedErrors
        )
    );
};
